return [{ json: { senderId } }];

const postback = $input.first().json.postback || '';
const senderId = $input.first().json.senderId;

const parts = postback.split('|');
const productId = parts[0] || null;
const size = parts[1] || null;
let addOn = parts[2] || null;
if (addOn?.startsWith('ADD_')) addOn = addOn.slice(4);

const isBite = productId?.startsWith('BK-');

if (!productId) {
  return {
    json: {
      error: 'Invalid product selection',
      senderId
    }
  };
}

return {
  json: {
    productId,
    size: size === 'NONE' ? null : size,
    addOn: addOn === 'NONE' ? null : addOn,
    isBite,
    senderId,
    needsDbFetch: true
  }
};

const productData = $input.all().find(item => item.json.ProductID)?.json;
const addOnData = $input.all().find(item => item.json.AddOnID)?.json;
const senderId = $input.first().json.senderId;

let requiredIngredients = {};
let directItems = {};

if (productData?.Ingredients && productData.Ingredients.length > 0) {
  productData.Ingredients.forEach(ingredientId => {
    if (!requiredIngredients[ingredientId]) {
      requiredIngredients[ingredientId] = 0;
    }
    requiredIngredients[ingredientId] += 1;
  });
}

if (productData?.ProductID?.startsWith('BK-') && productData.Quantity !== undefined) {
  directItems[productData.ProductID] = {
    required: 1,
    available: productData.Quantity,
    name: productData.Name
  };
}

if (addOnData?.Quantity !== undefined) {
  directItems[addOnData.AddOnID] = {
    required: 1,
    available: addOnData.Quantity,
    name: addOnData.Name
  };
}

return [
  {
    json: {
      productData,
      addOnData,
      requiredIngredients,
      directItems,
      needsIngredientCheck: Object.keys(requiredIngredients).length > 0,
      needsDirectCheck: Object.keys(directItems).length > 0,
      senderId,
      _stockCheckData: true
    }
  }
];

const currentData = $input.all();
const stockCheckData = $('Check Inventory Stock').first().json;

return currentData.map(item => ({
  json: {
    ...item.json,
    stockCheckData: stockCheckData
  }
}));

const allInputs = $input.all();
// Handle the case where stockData might be directly in the first input or in stockCheckData
const inputData = allInputs[0]?.json || {};
const stockData = inputData._stockCheckData ? inputData : (inputData.stockCheckData || {});
const senderId = $('extract values').first()?.json?.senderId;

// Safely destructure with defaults to prevent errors
const productData = stockData.productData || inputData.productData || {};
const addOnData = stockData.addOnData || inputData.addOnData;
const directItems = stockData.directItems || inputData.directItems || {};
const requiredIngredients = stockData.requiredIngredients || inputData.requiredIngredients || {};

const inventoryData = allInputs.filter(item => item.json.IngredientID || item.json.AddOnID);

let errors = [];
let warnings = [];

// Check if product is available and enabled
if (productData && (!productData.isEnabled && !productData.available)) {
  errors.push(`${productData.Name} is currently unavailable. Please select another item.`);
}

// BITES HANDLING: Direct check for bites items
if (productData && productData.ProductID && productData.ProductID.startsWith('BK-')) {
  // Bites have direct quantity tracking on the product
  if (productData.Quantity <= 0) {
    errors.push(`${productData.Name} is currently out of stock. Please select another item.`);
  } else if (productData.Quantity <= 5) {
    warnings.push(`Low stock: ${productData.Name} (${productData.Quantity} remaining)`);
  }
}

// Check add-on quantity
if (addOnData) {
  if (!addOnData.IsEnabled) {
    errors.push(`${addOnData.Name} add-on is unavailable. Please select another option.`);
  } else if (addOnData.Quantity <= 0) {
    errors.push(`${addOnData.Name} is currently out of stock. Please select an alternative.`);
  } else if (addOnData.Quantity <= 3) {
    warnings.push(`Low stock: ${addOnData.Name} (${addOnData.Quantity} remaining)`);
  }
}

// Check ingredients for non-bites items
if (Object.keys(requiredIngredients).length > 0) {
  Object.entries(requiredIngredients).forEach(([ingredientId, required]) => {
    const ingredient = inventoryData.find(inv => inv.json.IngredientID === ingredientId);
    if (!ingredient) {
      errors.push(`Ingredient ${ingredientId} not found in inventory`);
    } else if (!ingredient.json.IsEnabled) {
      errors.push(`Ingredient ${ingredient.json.Name} is currently disabled`);
    } else if (ingredient.json.Quantity < required) {
      errors.push(`Insufficient ${ingredient.json.Name} stock (need: ${required}, have: ${ingredient.json.Quantity})`);
    } else if (ingredient.json.Quantity <= 5) {
      warnings.push(`Low stock warning: ${ingredient.json.Name} (${ingredient.json.Quantity} remaining)`);
    }
  });
}

// Check add-ons in inventory
Object.entries(directItems || {}).forEach(([itemId, itemInfo]) => {
  // Skip bites items here - we already handled them above
  if (!itemId.startsWith('BK-')) {
    const addon = inventoryData.find(inv => inv.json.AddOnID === itemId);
    if (addon) {
      if (!addon.json.IsEnabled) {
        errors.push(`${addon.json.Name} add-on is currently disabled`);
      } else if (addon.json.Quantity < itemInfo.required) {
        errors.push(`Insufficient ${addon.json.Name} stock (need: ${itemInfo.required}, have: ${addon.json.Quantity})`);
      } else if (addon.json.Quantity <= 3) {
        warnings.push(`Low stock: ${addon.json.Name} (${addon.json.Quantity} remaining)`);
      }
    }
  }
});

return {
  json: {
    isValid: errors.length === 0,
    errors,
    warnings,
    productData,
    addOnData,
    senderId: senderId,
    canProceed: errors.length === 0,
    stockCheckData: stockData  // Pass this along for downstream nodes
  }
};

const cartData = $input.all().map(item => item.json);
const senderId = $('senderId Prepare').first().json.senderId;

// Handle empty cart
if (!cartData || cartData.length === 0) {
  return {
    json: {
      isEmpty: true,
      message: "Your cart is currently empty.",
      senderId
    }
  };
}

let subtotal = 0;
let totalItems = 0;
let processedItems = [];

// Handle nested cart structure
cartData.forEach(cart => {
  if (cart.cartItems && Array.isArray(cart.cartItems)) {
    cart.cartItems.forEach(cartItem => {
      if (cartItem.items && Array.isArray(cartItem.items)) {
        cartItem.items.forEach(nestedCart => {
          if (nestedCart.items && Array.isArray(nestedCart.items)) {
            // Access the actual product items
            nestedCart.items.forEach(actualItem => {
              processedItems.push(actualItem);
              subtotal += actualItem.totalPrice;
              totalItems += actualItem.quantity;
            });
          }
        });
      }
    });
  }
});

// If we didn't find any items in the nested structure, try a simpler approach
if (processedItems.length === 0) {
  // Try direct approach if nested structure doesn't work
  cartData.forEach(cart => {
    if (cart.items && Array.isArray(cart.items)) {
      cart.items.forEach(item => {
        processedItems.push(item);
        subtotal += item.totalPrice || 0;
        totalItems += item.quantity || 0;
      });
    }
  });
}

return {
  json: {
    isEmpty: processedItems.length === 0,
    cartItems: processedItems,
    itemCount: totalItems,
    subtotal,
    senderId
  }
};

const prepareUpsertData = $('Prepare Upsert Subtotal').first().json;
const { userId, subtotal, itemCount, cartItems } = prepareUpsertData;

let cartMessage = "📋 *YOUR CART* 📋\n\n";
let itemCounter = 1;

cartItems.forEach(item => {
  const productName = item.productName;
  const size = item.size;
  const quantity = item.quantity || 1; 
  const price = item.totalPrice.toFixed(2);

  cartMessage += `${itemCounter}. ${productName} (${size})\n`;
  cartMessage += `   ${quantity}x ₱${price}\n`;

  if (item.addOns && item.addOns.length > 0) {
    item.addOns.forEach(addon => {
      cartMessage += `   + ${addon.addOnName} (₱${addon.addOnPrice})\n`;
    });
  }

  cartMessage += "\n";
  itemCounter++;
});

cartMessage += `------------------------\n`;
cartMessage += `Subtotal: ₱${subtotal.toFixed(2)}\n\n`;
cartMessage += "What would you like to do next?";

return {
