  currency: 'IDR',
  items: order.items || [
    {
      name: 'Food Item',
      quantity: 1,
      price: order.totalAmount || 10000,
      category: 'Food'
    }
  ]
};

// Create payment request
const paymentOptions = {
  method: 'POST',
  headers: {
    'Authorization': `Basic ${Buffer.from(XENDIT_API_KEY + ':').toString('base64')}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(paymentData)
};

// Return the configuration for HTTP Request node
return {
  json: {
    url: `${XENDIT_BASE_URL}/v2/invoices`,
    options: paymentOptions,
    orderData: order,
    paymentData: paymentData
  }
}

// Extract and validate order information
const input = $input.first().json;

return {
  json: {
    userId: input.userId,
    customerName: input.customerName,
    customerEmail: input.customerEmail,
    customerPhone: input.customerPhone,
    items: input.items,
    totalAmount: input.totalAmount,
    deliveryMethod: input.deliveryMethod,
    deliveryAddress: input.deliveryAddress,
    orderNotes: input.orderNotes
  }
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const cartDisplayNode = $input.first().json;
const { senderId, subtotal, itemCount, cartItems } = cartDisplayNode;

return {
  json: {
    userId: senderId,
    subtotal: subtotal,
    itemCount: itemCount,
    cartItems: cartItems,
    updatedAt: new Date().toISOString()
  }
};
